INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('cse', 'Computer Science & Engineering', 'CSE', 'B.E. in Computer Science & Engineering', 2003, 120, '4 Years', 'Dr. Arun A. Kumbi', 'Associate Professor & HOD', 'arun.cse@agadiengcollege.com', '+91 8095791205', 'Welcome to the Department of Computer Science & Engineering at SKSVMACET, Laxmeshwar. Our department provides quality technical education to prepare rural students into global IT leaders through the C-Cube student association, coding bootcamps, and state-of-the-art computational laboratories.', 'https://agadiengcollege.com/wp-content/uploads/2024/02/Arun-K.jpg', 'To emerge as a premier centre of excellence in Computer Science and Engineering education, fostering competent software professionals with sound ethical and societal values.', '1. Impart quality education in core and emerging areas of computer science through outcome-based pedagogical practices.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('aiml', 'Artificial Intelligence & Machine Learning', 'AI & ML', 'B.E. in Computer Science & Engineering (AI & ML)', 2021, 60, '4 Years', 'Dr. Parashuram Baraki', 'Principal & Program Head, AI & ML', 'principal@agadiengcollege.com', '+91 9686042385', 'The AI & ML program at SKSVMACET equips future engineers with deep knowledge in neural networks, cognitive computing, automated reasoning, and data science to tackle next-generation technological revolutions.', 'https://agadiengcollege.com/wp-content/uploads/2025/12/dr-parashuram-baraki-e1767089044139.jpeg', 'To groom technically proficient engineers capable of leading breakthroughs in artificial intelligence, deep learning, and data engineering.', '1. Impart in-depth knowledge in machine learning algorithms, computer vision, and cognitive systems.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('ece', 'Electronics & Communication Engineering', 'ECE', 'B.E. in Electronics & Communication Engineering', 2003, 120, '4 Years', 'Dr. Subhas Meti', 'Professor & Head, Department of ECE', 'hod.ece@agadiengcollege.com', '+91 9449375371', 'The Department of ECE at SKSVMACET focuses on building strong foundations in semiconductor electronics, embedded microcontrollers, signal processing, and communication systems through practical experimentation.', 'https://agadiengcollege.com/wp-content/uploads/2024/02/Dr.Subhash-M.jpg', 'To be a centre of excellence in Electronics and Communication Engineering education and research, transforming rural students into globally recognized technocrats.', '1. Provide rigorous foundation in analog and digital electronics, VLSI design, and communication systems.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('eee', 'Electrical & Electronics Engineering', 'EEE', 'B.E. in Electrical & Electronics Engineering', 2003, 60, '4 Years', 'Dr. R. M. Patil', 'Professor & Head, Dept. of EEE & IQAC Coordinator', 'hod.eee@agadiengcollege.com', '+91 9975052933', 'Electrical engineering powers modern civilization. Our department combines fundamental power engineering with renewable energy systems, electric vehicle technologies, and industrial automation.', 'https://agadiengcollege.com/wp-content/uploads/2024/02/Dr.-R-M-Patil.jpg', 'To provide quality electrical engineering education, instilling technical expertise, research curiosity, and professional ethics.', '1. Provide comprehensive education in electrical machines, power systems, and power electronics.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('civil', 'Civil Engineering', 'CV', 'B.E. in Civil Engineering', 2009, 60, '4 Years', 'Dr. Swapna Channagoudar', 'Associate Professor & HOD', 'hod.civil@agadiengcollege.com', '+91 8867617379', 'Civil engineering builds the backbone of society. At SKSVMACET, our civil department is known across North Karnataka for consultancy in concrete testing, geotechnical soil analysis, and structural consultancy for PWD and local municipalities.', 'https://agadiengcollege.com/wp-content/uploads/2024/01/Dr.-Swapna.jpg', 'To produce socially committed, innovative civil engineers capable of designing sustainable and resilient infrastructure.', '1. Deliver sound training in structural design, geotechnical engineering, and environmental analysis.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('mech', 'Mechanical Engineering', 'ME', 'B.E. in Mechanical Engineering', 2003, 60, '4 Years', 'Dr. Sreenivasa R.', 'Associate Professor & Head, Department of Mechanical Engineering', 'hod.mech@agadiengcollege.com', '+91 9606476159', 'Mechanical engineering is the mother of all engineering disciplines. Through our active student association "TORQUE", our students participate in machine fabrication, thermal experiments, and technical project exhibitions.', 'https://agadiengcollege.com/wp-content/uploads/2026/11/sreenivasa.jpeg', 'To produce competent mechanical engineers who excel in machine design, thermal sciences, and modern manufacturing with ethical values.', '1. Impart quality education in mechanics, thermodynamics, and manufacturing processes.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('ise', 'Information Science & Engineering', 'ISE', 'B.E. in Information Science & Engineering', 2007, 60, '4 Years', 'Dr. Arunkumar Joshi', 'Associate Professor & In-Charge Head, Department of ISE', 'hod.ise@agadiengcollege.com', '+91 9663579700', 'The Department of Information Science & Engineering focuses on data systems, software architecture, mobile application development, and cybersecurity to meet dynamic enterprise standards.', 'https://agadiengcollege.com/wp-content/uploads/2024/02/Dr.-Arun-J.jpg', 'To be a recognized department of excellence in information technology education and software innovation.', '1. Impart sound technical education in information systems, networks, and data management.
INSERT INTO departments (id, name, short_name, degree, established, intake, duration, hod_name, hod_designation, hod_email, hod_phone, hod_message, hod_photo, vision, mission, banner_image, about_text, curriculum_highlights) VALUES ('basic-science', 'First Year Engineering (General Science)', 'FYE', 'Foundational First-Year Basic Sciences', 2003, 420, '1 Year (Foundational)', 'Dr. Girish Yatinahalli', 'Associate Professor (Mathematics) & Lead, First Year Engineering', 'girish.math@agadiengcollege.com', '+91 9844950991', 'The First Year Engineering department lays the rock-solid foundation for all aspiring engineers in engineering mathematics, physics, chemistry, professional communication, and computational thinking under VTU.', 'https://agadiengcollege.com/wp-content/uploads/2024/06/Dr.-Girish-Y.jpg', 'To impart fundamental scientific acumen and moral values to first-year engineering students for successful academic and professional journeys.', '1. Build strong conceptual foundation in applied mathematics, engineering physics, and chemistry.
