INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (1, 'cse', 'C-Cube Computing & Programming Lab', 'Central computational laboratory equipped for Data Structures, Java, Python, and C programming practicals for 2KA engineering students.', '60x High-Speed Dell Optiplex PCs, Ubuntu & Windows, 1 Gbps LAN, Eclipse, VS Code', 'https://images.unsplash.com/photo-1562774053-701939374585?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (2, 'cse', 'DBMS & Web Technologies Lab', 'Dedicated database management systems laboratory for relational SQL design, full stack development, and VTU practical exams.', 'Intel Core i5 systems, MySQL, Oracle 11g, Node.js development suites', 'https://images.unsplash.com/photo-1581092335397-9583fe92d232?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (3, 'aiml', 'Artificial Intelligence & Deep Learning Lab', 'GPU-accelerated lab for neural network modeling, computer vision, and cognitive data engineering.', 'Multi-core Workstations, NVIDIA RTX GPUs, TensorFlow, PyTorch, Jupyter Lab', 'https://images.unsplash.com/photo-1555255707-c07966088b7b?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (4, 'ece', 'VLSI & Embedded Systems Lab', 'Electronics design automation and microcontrollers facility for digital integrated circuit design and ARM programming.', 'Cadence EDA Suite, Xilinx Vivado, Keil MicroVision, ARM Cortex development boards', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (5, 'eee', 'Electrical Machines & Power Systems Lab', 'Comprehensive laboratory for analyzing AC/DC motors, alternators, transformers, and industrial motor drives.', 'AC/DC Motor-Generator sets, 3-Phase Transformers, Loading Rheostats, Digital Power Meters', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (6, 'civil', 'Material Testing & Geotechnical Testing Lab', 'Certified testing center providing concrete compressive testing, tensile testing, and soil mechanics consultancy for PWD projects in Gadag district.', '2000 kN Universal Testing Machine (UTM), Compression Testing Machine, Triaxial Shear Apparatus', 'https://images.unsplash.com/photo-1581093458791-9f3c3900df4b?w=600&auto=format&fit=crop&q=80');
INSERT INTO labs (id, department_id, name, description, equipment, image) VALUES (7, 'mech', 'Machine Shop & Fluid Machinery Lab', 'Comprehensive manufacturing workshop containing center lathes, shaping machines, milling, and hydraulic turbine test rigs.', 'Heavy Duty Center Lathes, Shaper & Milling Machines, Pelton Wheel, Francis Turbine', 'https://images.unsplash.com/photo-1504917599217-d4dc5ebe6122?w=600&auto=format&fit=crop&q=80');
INSERT INTO events (id, title, subtitle, category, event_date, event_time, venue, description, banner_image, is_featured, is_banner, registration_link, organizer) VALUES (5, 'MELANZE: Annual National Techno-Cultural Fest', 'Flagship Techno-Cultural Festival: Project Exhibition, Coding Hackathon, Robotics & Cultural Stages', 'Tech Fest', 'March 27-28, 2026', '09:30 AM - 08:30 PM', 'SKSVMACET Main Campus Grounds, Open Air Auditorium & Central Labs, Lakshmeshwar', 'Melanze is the premier annual national-level techno-cultural festival of SKSVMACET Lakshmeshwar. Bringing together engineering talent from institutions across Karnataka for hardware and software project exhibitions, C-Cube 24-hour coding sprints, robotics arena, bridge-making contests, paper presentations, gaming, and vibrant cultural music and dance nights.', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1600&auto=format&fit=crop&q=80', 1, 1, 'https://agadiengcollege.com/melanze', 'SKSVMACET Student Council & Cultural Committee');
INSERT INTO events (id, title, subtitle, category, event_date, event_time, venue, description, banner_image, is_featured, is_banner, registration_link, organizer) VALUES (6, 'ICMRTET: International Conference on Multi-disciplinary Research Trends in Engineering and Technology', 'Peer-Reviewed Research Paper Presentations, Keynotes by Eminent Scientists & Industry Experts', 'Conference', 'April 24-25, 2026', '10:00 AM - 05:00 PM', 'Sir M. Visvesvaraya Seminar Hall Complex, SKSVMACET Lakshmeshwar', 'SKSVMACET flagship international academic conference connecting researchers, academicians, and industry pioneers to present breakthrough findings across Computer Science, Artificial Intelligence, Electronics, Mechanical, and Civil Engineering.', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=1600&auto=format&fit=crop&q=80', 1, 1, 'https://agadiengcollege.com/icmrtet', 'SKSVMACET Research & Development (R&D) Cell');
INSERT INTO events (id, title, subtitle, category, event_date, event_time, venue, description, banner_image, is_featured, is_banner, registration_link, organizer) VALUES (7, 'TORQUE: Mechanical Engineering Student Convention & Workshop', 'Industrial Innovation, Automotive CAD Design & 3D Prototyping', 'Workshop', 'May 08, 2026', '10:00 AM - 04:30 PM', 'Mechanical Engineering Department Block, SKSVMACET Lakshmeshwar', 'Organized by the TORQUE Mechanical Association under Dr. Sreenivasa R. Features hands-on masterclasses in 3D CAD modeling, CNC machining demonstrations, industrial automation, and student prototype displays.', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1600&auto=format&fit=crop&q=80', 1, 0, 'https://agadiengcollege.com/torque', 'TORQUE Mechanical Association');
INSERT INTO events (id, title, subtitle, category, event_date, event_time, venue, description, banner_image, is_featured, is_banner, registration_link, organizer) VALUES (8, 'Annual Mega Pool Campus Recruitment Drive', 'Top MNCs & Core Engineering Companies Hiring Final & Pre-Final Year Engineers', 'Placement', 'May 18-19, 2026', '08:30 AM Onwards', 'Campus Placement & Training Centre, SKSVMACET Lakshmeshwar', 'Coordinated by TPO Cell leads Mrs. Rajeshwari Gamanagatti, Dr. Shivarajkumar Goudar, Mr. Manjunathraddi Bentur, and Mr. Keshav Negalur. On-campus and pool drives with Infosys, Wipro, TCS, Cognizant, Xoriant, and Powercon.', 'https://images.unsplash.com/photo-1521737711867-e3b97375f902?w=1600&auto=format&fit=crop&q=80', 0, 0, 'https://agadiengcollege.com/placements', 'Training & Placement Cell (TPO)');
INSERT INTO events (id, title, subtitle, category, event_date, event_time, venue, description, banner_image, is_featured, is_banner, registration_link, organizer) VALUES (9, 'Annual Special Rural Community NSS Camp', 'Village Health Awareness, Tree Plantation, Clean Drinking Water & Watershed Campaigns', 'Cultural', 'June 02-08, 2026', '7-Day Residential Camp', 'Adopted Rural Panchayats, Lakshmeshwar Taluk, Gadag District', 'Organized by the SKSVMACET National Service Scheme (NSS) Unit under the Ministry of Youth Affairs and Sports. Engineering student volunteers engage in village health awareness, tree plantation drives, computer literacy for school students, and watershed development in Gadag district.', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=1600&auto=format&fit=crop&q=80', 0, 0, 'https://agadiengcollege.com/nss', 'SKSVMACET National Service Scheme (NSS)');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (6, 'Our Honorable Chairman Sri Harshavardhan V. Agadi Has Announced Free Engineering Education for Children of Fallen Soldiers at Our Institute', 'March 10, 2026', 'Welfare & Scholarships', 1, 1, 'https://agadiengcollege.com', 'In a noble philanthropic tribute to the brave martyrs of the Indian Armed Forces, our Honorable Chairman Sri Harshavardhan V. Agadi has announced 100% free Engineering Education at SKSVMACET Lakshmeshwar for the children of fallen soldiers. Full tuition waiver and complete institutional support are provided across all B.E. programs. Eligible candidates can contact the Chairman’s Office or Principal desk directly.');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (7, '50% KCET Fee Concession Scheme & ₹20 Lakhs Annual Management Scholarships for Meritorious Students', 'March 08, 2026', 'Scholarships', 1, 0, 'https://agadiengcollege.com', 'S.V.M.V.V. Society announces 50% CET tuition fee concession for students securing KCET rank under 30,000 or 95%+ in II PUC, alongside ₹20 Lakhs in annual scholarships distributed to deserving rural students.');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (8, 'B.E. Admissions 2026-27 Open at SKSVMACET: KCET Code E167 / COMED-K & Management Quota', 'March 07, 2026', 'Admissions', 1, 1, 'https://agadiengcollege.com/admissions', 'Applications are invited for admissions into B.E. programs (CSE, AI&ML, ECE, EEE, Civil, Mechanical, ISE) for academic year 2026-27. Contact the Principal desk at +91 9686042385 or Admissions helpline +91 8378 267101.');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (9, 'VTU Belagavi Notification: Submission of Examination Application Forms for USN 2KA Batches', 'March 05, 2026', 'Examination', 1, 1, 'https://vtu.ac.in', 'All students with USN starting with 2KA (2KA20, 2KA21, 2KA22, 2KA23 batches) must submit odd/even semester examination forms through the VTU college examination coordinator before the deadline.');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (10, 'Prof. Venkata Subba Setti Library: Return & Re-issue of Odd Semester Book Bank Volumes', 'March 02, 2026', 'Academics', 1, 0, '/library', 'Students are requested to return Book Bank books issued for the semester to the circulation counter between 9:30 AM to 5:30 PM. Renewal for even semester begins next week via Koha OPAC.');
INSERT INTO announcements (id, title, date, category, is_new, is_urgent, document_url, details) VALUES (11, 'TPO Notice: Soft Skills & Aptitude Bootcamp for 6th Semester (USN 2KA23 Batch)', 'February 27, 2026', 'Circulars', 0, 0, '/placements', 'Mandatory campus recruitment training session conducted by Training & Placement Cell coordinators starting Monday at the Main Auditorium.');
